import secrets

def validate_reset_token(user_id, token, token_store):
    stored_data = token_store.get(user_id)
    if stored_data is None:
        return False

    stored_token = stored_data.get('token')
    expiry = stored_data.get('expiry')

    try:
        if secrets.compare_digest(token, stored_token):
            import time
            if time.time() < expiry:
                return True
    except (TypeError, AttributeError):
        pass

    return False
